import React from 'react';
import './PostItem.css';

const PostItem = ({ post, onEdit, onDelete }) => {
  // Format date to a readable string
  const formattedDate = new Date(post.publishedDate).toLocaleDateString('en-US', {
    year: 'numeric',
    month: 'short',
    day: 'numeric'
  });

  return (
    <div className="card h-100 shadow-sm">
      <div className="card-body">
        {/* Post Title */}
        <h5 className="card-title text-primary fw-bold">{post.title}</h5>

        {/* Author & Date */}
        <h6 className="card-subtitle mb-3 text-muted small">
          By <strong>{post.author}</strong> • {formattedDate}
        </h6>

        {/* Post Content */}
        <p className="card-text text-secondary">{post.content}</p>
      </div>

      {/* Edit & Delete Action Buttons */}
      <div className="card-footer bg-white border-top-0 d-flex justify-content-end gap-2 pb-3">
        <button
          type="button"
          className="btn btn-sm btn-outline-primary"
          onClick={() => onEdit(post)}
        >
          Edit
        </button>
        <button
          type="button"
          className="btn btn-sm btn-outline-danger"
          onClick={() => onDelete(post._id)}
        >
          Delete
        </button>
      </div>
    </div>
  );
};

export default PostItem;
